        .addColumn("itemId", "text", (col: any) => col.primaryKey())
        .addColumn("winningBidder", "text")
        .addColumn("winningAmount", "integer")
        .addColumn("closed", "integer")
        .execute();
    },
    async down(db: any) {
      await db.schema.dropTable("auctions").execute();
